import {
  readFileSync,
  readdirSync,
  mkdirSync,
  writeFileSync,
  unlinkSync,
} from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
const canonical = join(root, "packages/actions");
const files = new Map();
files.set(
  "action.yml",
  "# Generated by npm run build:actions. Edit packages/actions/actions/setup-github-emulator/action.yml.\n" +
    readFileSync(
      join(canonical, "actions/setup-github-emulator/action.yml"),
      "utf8",
    ),
);
for (const file of ["main.mjs", "post.mjs", "shared.mjs"]) {
  files.set(
    `dist/github-emulator/${file}`,
    readFileSync(join(canonical, "src", file)),
  );
}
for (const file of [
  "Dockerfile",
  "package.json",
  "package-lock.json",
  ".dockerignore",
]) {
  files.set(
    `dist/github-emulator/docker/${file}`,
    readFileSync(join(root, "packages/emulate-github/docker", file)),
  );
}
function existingFiles(directory, relative = "") {
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const path = join(relative, entry.name);
    return entry.isDirectory()
      ? existingFiles(join(directory, entry.name), path)
      : [path];
  });
}
if (process.argv.includes("--check")) {
  const mismatches = [];
  for (const [name, expected] of files) {
    try {
      if (!readFileSync(join(root, name)).equals(Buffer.from(expected)))
        mismatches.push(name);
    } catch {
      mismatches.push(name);
    }
  }
  try {
    for (const file of existingFiles(join(root, "dist/github-emulator"))) {
      if (!files.has(`dist/github-emulator/${file}`))
        mismatches.push(`Unexpected generated file: ${file}`);
    }
  } catch {
    /* Missing output is already reported above. */
  }
  if (mismatches.length) {
    console.error(
      `Action distribution is stale. Run npm run build:actions.\n${mismatches.join("\n")}`,
    );
    process.exitCode = 1;
  } else
    console.log(
      "Root action metadata and runtime match their package sources.",
    );
} else {
  try {
    for (const file of existingFiles(join(root, "dist/github-emulator"))) {
      if (!files.has(`dist/github-emulator/${file}`))
        unlinkSync(join(root, "dist/github-emulator", file));
    }
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }
  for (const [name, content] of files) {
    mkdirSync(dirname(join(root, name)), { recursive: true });
    writeFileSync(join(root, name), content);
  }
  console.log(`Generated ${files.size} action distribution files.`);
}
